<script>(function(){document.querySelectorAll('[data-copy-target]').forEach(function(button){button.addEventListener('click',async function(){var target=document.getElementById(button.dataset.copyTarget),feedback=button.parentElement.querySelector('.copy-feedback');if(!target)return;var value=target.textContent.trim();try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(value);}else{var field=document.createElement('textarea');field.value=value;field.style.position='fixed';field.style.opacity='0';document.body.appendChild(field);field.select();var copied=document.execCommand('copy');field.remove();if(!copied)throw new Error('copy failed');}feedback.textContent='Đã sao chép';}catch(error){feedback.textContent='Không sao chép được. Hãy chọn và sao chép key.';}});});})();</script>
<?php endif; ?>
